INSERT INTO "mb_drinks" VALUES
    ('peridothk', 'Más Fotos', 'An amaretto and mezcal sour with kumquat and a citrus cloud topping.', 'Oaxaca Terroir programme. Served on the rocks. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('peridothk', 'Maíz Trilogy', 'A corn-led old fashioned style drink built on corn whiskey, bourbon and corn liqueur.', 'Oaxaca Terroir programme. Served on the rocks. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Rocks', NULL),
    ('peridothk', 'Tropical Verdict', 'A tropical rum drink with jackfruit cordial, maraschino and lime.', 'Oaxaca Terroir programme. Served straight up. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'Answering Spicy Questions', 'A tequila sour with chilli, hibiscus and Tajín, with a choice of chilli intensity.', 'Oaxaca Terroir programme. Guests choose the chilli intensity (light, mild or very hot); served straight up or on the rocks. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('peridothk', 'Dirty Pozole', 'A savoury martini-style drink using tomato and avocado oil washed gin and distilled hominy.', 'Oaxaca Terroir programme. Served straight up. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Martini', NULL),
    ('peridothk', 'Mango Provocador', 'A fruity and herbal gin drink with mango, Green Chartreuse and vanilla.', 'Oaxaca Terroir programme. Served straight up. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'Ice and Fire Sgroppino', 'A sgroppino with lime sorbet, corn liqueur, mezcal and sparkling sake.', 'Oaxaca Terroir programme. Served in a silver coupe. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'El Beso del Desierto', 'A red-berry and earthy mezcal drink with clarified prickly pear and vermouth.', 'Oaxaca Terroir programme. Served straight up. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Wine', NULL),
    ('peridothk', 'Cempōhualxōchitl', 'A floral gin drink built on a house-blended gin rested in beeswaxed bottles, with marigold and agave cordial.', 'Oaxaca Terroir programme. Served straight up. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('peridothk', 'Nude Study', 'A vodka and yuzu drink with timur pepper cordial, hot bitters and a Japanese citrus cloud.', 'Kagoshima Terroir programme (the opening menu, still listed as an all-time classic).. Source: Peridot beverage menu (PDF). Named by Time Out among highlights of the opening programme.', NULL, 2025, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'Yuzu''s Reply', 'A bitter, citrusy Negroni-leaning sour with komikan gin, yuzu liqueur and Campari.', 'Kagoshima Terroir programme (the opening menu, still listed as an all-time classic).. Source: Peridot beverage menu (PDF).', NULL, 2025, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'Durian''s Consent', 'A tropical shochu and rum drink with Musang King durian cordial and maraschino.', 'Kagoshima Terroir programme (the opening menu, still listed as an all-time classic).. Source: Peridot beverage menu (PDF). Named by Time Out among highlights of the opening programme.', NULL, 2025, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'The Blush', 'A non-alcoholic drink with hassaku and bergamot cordial, salty lime kombucha and palo santo.', 'Non-alcoholic (''mocktail'') on the menu. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('peridothk', 'Volcanic Guava', 'A non-alcoholic drink with clarified guava, sour cherry and garam masala wine.', 'Non-alcoholic (''mocktail'') on the menu. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Coupe', NULL),
    ('peridothk', 'Dancing with Memories', 'A savoury non-alcoholic drink with Clamato, yuzu, shoyu, tamarind and chipotle.', 'Non-alcoholic (''mocktail'') on the menu. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('peridothk', 'Alex''s Note', 'A creamy, tropical non-alcoholic drink with roasted pineapple, coconut and sweet potato water.', 'Non-alcoholic (''mocktail'') on the menu. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', 'Highball', NULL),
    ('peridothk', 'Henderson Green', 'A non-alcoholic drink with pineapple, whey, pandan and peach cordial and sparkling jasmine tea.', 'Non-alcoholic (''mocktail'') on the menu. Source: Peridot beverage menu (PDF).', NULL, 2026, 'francois.cavelier', NULL, NULL),
    ('barmindhk', 'Whispering Blooms', 'A light, floral drink built on jasmine tea, elderflower and hibiscus.', 'Base spirit not named in the review. Source: The Beat Asia review of the eight opening signatures (July 2025).', NULL, 2025, 'jo.lo', NULL, NULL),
    ('barmindhk', 'Monk''s Sea Breeze', 'A savoury-tropical drink of rum, passion fruit, tomato and Lillet, served with an edible quail-egg-shaped shell filled with passion fruit syrup.', 'Time Out''s December 2025 piece describes a drink of the same make-up and presentation as The Cha Chaan Teng, so it may have been renamed. Source: The Beat Asia review of the eight opening signatures (July 2025).', NULL, 2025, 'jo.lo', NULL, NULL),
    ('barmindhk', 'A Taste of Home', 'A tequila drink with bitter melon and fermented black bean, inspired by home cooking from the founders'' childhoods.', 'Cantonese-flavoured signature. Source: The Beat Asia review of the eight opening signatures (July 2025).', NULL, 2025, 'jo.lo', NULL, NULL),
    ('barmindhk', 'Campino Dreams', 'A strawberry, yoghurt-washed drink with white miso, reminiscent of childhood sweets.', 'Base spirit not named in the review. Source: The Beat Asia review of the eight opening signatures (July 2025).', NULL, 2025, 'jo.lo', NULL, NULL),
    ('barmindhk', 'Streetwise Boulevardier', 'A bourbon Boulevardier twist with Sichuan pepper and chilli oil.', 'Riff on the Boulevardier; served with a sea snail garnish. Source: The Beat Asia review of the eight opening signatures (July 2025).', 'Boulevardier', 2025, 'jo.lo', NULL, NULL),
