    ('bardandolo_venice', 'Doge', 'The bar''s house cocktail named for the Venetian doges, a fruity mix of vodka, blended strawberries, bitter aperitivo and cranberry juice.', 'Described in the Italian cocktail-bar guide as the cocktail not to miss at Bar Dandolo.', NULL, NULL, NULL, NULL, NULL),
    ('bardandolo_venice', 'Vesper Martini', 'A Vesper-style martini with gin, vodka, dry vermouth and a few drops of Angostura, made in honour of the bar''s appearance in a James Bond film.', 'Hotel text promotes it as a Vesper Martini in true Bond style.', 'Vesper', NULL, NULL, NULL, NULL),
