    ('artsbarvenice', 'Willful Dart', 'A milk-washed rum and bourbon drink built on Spanish horchata with a hint of liquorice.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Eugenio Recuenco''s photograph 365 Azzarret.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Still Waiting', 'A cocoa, apricot and vanilla drink with tart verjus and a foam cloud, an homage to an Austrian cake.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Erwin Wurm''s work ...Waiting.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Urban Grid', 'A gin martini served in three differently sized glasses for yellow citrus, red spice and blue juniper.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Piet Mondrian''s Composition C No. III.', 'Martini', NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Silver Dreams', 'A vodka and champagne drink with elderflower liqueur and a popcorn syrup.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Andy Warhol''s Shots Marilyn.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Canvas Temptation', 'A blue-green drink of grape spirit with fig and tonka cordial, chili and spirulina.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Picasso''s Les Demoiselles d''Avignon.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Through The Trees', 'A Collins with aquavit, toasted barley syrup and hop soda, finished with a whisper of absinthe.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Edvard Munch''s The Scream.', NULL, NULL, NULL, 'Collins', NULL),
    ('artsbarvenice', 'Oriental Shapes', 'A Japanese whisky drink with an oriental fruit syrup and Venetian Amaro Cipriani.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Carlo Scarpa''s Tomb Brion.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Aw Vision', 'A vivid red baijiu drink with a pineapple and black pepper shrub, balanced with Select.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Ai Weiwei''s The White Chandelier.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'The Negroni Desire', 'A twist on the Negroni with calvados, a blend of four vermouths and Venissa made from lagoon ingredients.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Salvador Dali''s Birth of Liquid Desires.', 'Negroni', NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Canal Art', 'A mezcal drink with a Sant''Erasmo artichoke cordial, topped with pink air and a salted aromatic spray.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Banksy''s Venice Biennale graffiti of 2019.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Britannia 1201', 'The bar''s interpretation of an alcohol-free martini, dedicated to Monet, who stayed in the building when it was the Grand Hotel Britannia.', 'One of the Signature Cocktails, inspired by Claude Monet''s Il Canal Grande. Alcohol-free; no ingredients listed.', NULL, NULL, NULL, NULL, NULL),
    ('artsbarvenice', 'Spirit Illusions', 'An alcohol-free spritz that rethinks the aperitivo.', 'One of the Signature Cocktails, each inspired by an artist or artwork; this one is inspired by Karen LaMonte''s glass sculpture Reclining Nocturne. Alcohol-free; no ingredients listed.', NULL, NULL, NULL, NULL, NULL),
    ('double_down_saloon_nyc', 'Ass Juice', 'The house brown punch served in a small cup, a sweet blend of assorted liquors with a secret recipe.', 'Signature of both the Las Vegas and New York bars; the bartender calls the recipe secret, so no ingredients are published. Described by The New Yorker in 2018 as a sweet punch.', NULL, NULL, NULL, NULL, NULL),
    ('double_down_saloon_nyc', 'Bacon Martini', 'A martini made with bacon-fat-infused vodka, garnished with a strip of bacon.', 'Wikipedia credits P Moss with inventing it at the Las Vegas bar in 1998; The New Yorker notes both bars are known for bacon martinis.', 'Martini', NULL, NULL, NULL, NULL),
