-- DRAFT. Local stack only until Kevin's OK.
--
-- Bars from Kevin's own Google Maps lists (NYC, Melbourne, Paris, Hong Kong,
-- Kuala Lumpur, Seoul, Singapore, Penang, Manila, Mumbai, Delhi, Goa, Sydney,
-- Venice) that weren't in the app yet: 714 bars, 1030 new people,
-- 1215 positions, 162 awards, 6392 drinks and 501 menus.
-- Researched from each bar's own site and press; every row keeps its source.
-- Same shapes and rules as the earlier seeds (20261008000000_cocktail_omakase):
-- public, unclaimed profiles, no photos of people, drinks credited to their
-- bar (and maker where a source says so) at 'suggested', ingredients as the
-- menus list them and measures only where published.
--
-- Safe to re-run: a bar already here under the same name nearby, or a handle
-- taken, is left alone, and so is anything else already present.

-- Seeded drinks don't queue automatic sketches (nobody to bill for them).
SET "app.image_worker" = 'on';

-- --- Bars ---

CREATE TEMP TABLE "mb_bars" ("handle" text, "name" text, "bio" text, "website" text, "instagram" text,
    "social_links" text[], "locality" text, "address_line" text, "postcode" text, "city" text, "region" text,
    "country_code" text, "latitude" double precision, "longitude" double precision, "is_closed" boolean,
    "closed_year" int);


                                 "is_public", "locality", "address_line", "postcode", "city", "region", "country_code",
                                 "latitude", "longitude", "is_closed", "closed_year")
SELECT 'bar', v.handle, v.name, v.bio, v.website, v.instagram, v.social_links, true, v.locality, v.address_line,
       v.postcode, v.city, v.region, v.country_code, v.latitude, v.longitude, v.is_closed, v.closed_year::smallint
FROM "mb_bars" v
-- Not a second copy of a bar someone already added (add_venue's rule).
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profiles" p
    WHERE p.kind = 'bar' AND p.latitude BETWEEN v.latitude - 0.002 AND v.latitude + 0.002
      AND private.venue_name_key(p.display_name) = private.venue_name_key(v.name)
      AND private.distance_km(v.latitude, v.longitude, p.latitude, p.longitude) <= 0.15
)
ON CONFLICT ("handle") DO NOTHING;

-- Bars already here without an address (20261008950100_cocktail_family_tree):
-- fill their gaps, never overwrite, and give them the researched drinks too.
CREATE TEMP TABLE "mb_fill" (LIKE "mb_bars");
UPDATE "public"."profiles" p SET
    "bio" = coalesce(p.bio, v.bio), "website" = coalesce(p.website, v.website),
    "instagram" = coalesce(p.instagram, v.instagram), "social_links" = coalesce(p.social_links, v.social_links),
    "locality" = coalesce(p.locality, v.locality), "address_line" = coalesce(p.address_line, v.address_line),
    "postcode" = coalesce(p.postcode, v.postcode), "region" = coalesce(p.region, v.region),
    "country_code" = coalesce(p.country_code, v.country_code),
    "latitude" = coalesce(p.latitude, v.latitude), "longitude" = coalesce(p.longitude, v.longitude)
FROM "mb_fill" v
WHERE p.kind = 'bar' AND p.handle = v.handle AND (p.latitude IS NULL OR p.website IS NULL OR p.instagram IS NULL);

CREATE TEMP TABLE "mb_ids" AS
SELECT DISTINCT ON (p.handle) p.handle, p.id FROM "public"."profiles" p
WHERE p.kind = 'bar' AND p.handle IN (SELECT handle FROM "mb_bars" UNION ALL SELECT handle FROM "mb_fill")
ORDER BY p.handle, p.created_at;

