) AS v("handle", "award", "year", "position", "title", "source_url")
JOIN "mb_ids" p ON p.handle = v.handle
-- Same award already there under slightly different wording.
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profile_awards" x
    WHERE x.profile_id = p.id AND x.award = v.award AND x.year = v.year::smallint
      AND (x.position IS NOT DISTINCT FROM v.position::smallint)
      AND regexp_replace(lower(coalesce(x.title, '')), '^the | award$', '', 'g')
        = regexp_replace(lower(coalesce(v.title, '')), '^the | award$', '', 'g')
)
ON CONFLICT DO NOTHING;

-- --- Drinks ---

CREATE TEMP TABLE "mb_drinks" ("handle" text, "name" text, "description" text, "notes" text, "riff_of" text,
    "year" int, "creator" text, "glass" text, "method" text);
CREATE TEMP TABLE "mb_lines" ("handle" text, "drink" text, "pos" int, "ingredient" text, "amount" numeric,
    "unit" text, "prep" text);
CREATE TEMP TABLE "mb_cocreators" ("handle" text, "drink" text, "person" text);
CREATE TEMP TABLE "mb_menu" ("handle" text, "edition" text, "year" int, "month" int, "pos" int, "drink" text);





-- Nor flavour jobs: with CATALOG_AI_FILL=on each one is a paid AI fill for a
-- drink with no venue (same rule as 20261007190000_bar_history). Note the
-- queue for these bars' drinks now and put it back at the end.
CREATE TEMP TABLE "mb_flavor_jobs" AS
SELECT j.* FROM "private"."item_flavor_jobs" j
JOIN "public"."items" i ON i.id = j.item_id
WHERE i.item_type = 'cocktail' AND i.bar_id IS NULL AND i.origin_bar_profile_id IN (SELECT id FROM "mb_ids");

                              "origin_year", "creator_profile_id", "credit_status")
SELECT d.name, 'cocktail', d.description, d.notes, CASE WHEN c.id IS NULL THEN 'Original' ELSE 'Varient' END, c.id, p.id,
       d.year::smallint, cr.id, CASE WHEN cr.id IS NULL THEN NULL ELSE 'suggested'::public.credit_status END
FROM "mb_drinks" d
JOIN "mb_ids" p ON p.handle = d.handle
LEFT JOIN "public"."profiles" cr ON cr.kind = 'person' AND cr.handle = d.creator
LEFT JOIN LATERAL (
    SELECT c.id FROM "public"."items" c
    WHERE c.is_catalog AND c.item_type = 'cocktail' AND lower(btrim(c.name)) = lower(d.riff_of)
    ORDER BY c.created_at LIMIT 1
) c ON true
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."items" i
    WHERE i.item_type = 'cocktail' AND i.bar_id IS NULL AND i.origin_bar_profile_id = p.id
      AND public.menu_name_key(i.name) = public.menu_name_key(d.name)
);

ALTER TABLE "mb_drinks" ADD COLUMN "item_id" uuid;
UPDATE "mb_drinks" d SET "item_id" = (
    SELECT i.id FROM "public"."items" i JOIN "mb_ids" p ON p.handle = d.handle
    WHERE i.item_type = 'cocktail' AND i.bar_id IS NULL AND i.origin_bar_profile_id = p.id
      AND public.menu_name_key(i.name) = public.menu_name_key(d.name)
    ORDER BY (i.name = d.name) DESC, i.created_at, i.id LIMIT 1
);
DELETE FROM "mb_drinks" WHERE "item_id" IS NULL;

SELECT d.item_id, pr.id
FROM "mb_cocreators" x
JOIN "mb_drinks" d ON d.handle = x.handle AND d.name = x.drink
JOIN "public"."profiles" pr ON pr.kind = 'person' AND pr.handle = x.person
ON CONFLICT DO NOTHING;

-- Glass and method where a source names them; only filling gaps.
UPDATE "public"."items" i SET
    "glassware_id" = coalesce(i.glassware_id, (SELECT g.id FROM "public"."items" g WHERE g.item_type = 'glassware' AND g.bar_id IS NULL AND lower(g.name) = lower(d.glass) ORDER BY g.created_at LIMIT 1))
FROM "mb_drinks" d
WHERE i.id = d.item_id AND d.glass IS NOT NULL;

SELECT d.item_id, m.id, 0
FROM "mb_drinks" d
JOIN LATERAL (
    SELECT m.id FROM "public"."items" m WHERE m.item_type = 'method' AND m.bar_id IS NULL AND lower(m.name) = lower(d.method)
    ORDER BY m.created_at LIMIT 1
) m ON true
WHERE d.method IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "public"."item_methods" x WHERE x.item_id = d.item_id);

-- --- Ingredient lines, only for drinks that have none ---

ALTER TABLE "mb_lines" ADD COLUMN "item_id" uuid;
UPDATE "mb_lines" l SET "item_id" = d.item_id
FROM "mb_drinks" d
WHERE d.handle = l.handle AND d.name = l.drink
  AND NOT EXISTS (SELECT 1 FROM "public"."recipes" r WHERE r.recipe_item_id = d.item_id);
DELETE FROM "mb_lines" WHERE "item_id" IS NULL;

-- Shared ingredients: the one the app already counts as the same name
-- (public.resolve_ingredient: same key, or an alias), else a new one per
-- name key. New ones are a menu's wording, so they stay out of ingredient
-- search; drink pages still show them.
CREATE TEMP TABLE "mb_ingredients" AS
SELECT DISTINCT ON (public.ingredient_key(l.ingredient)) public.ingredient_key(l.ingredient) AS key, l.ingredient AS name,
       public.resolve_ingredient(l.ingredient) AS id
FROM "mb_lines" l
WHERE public.ingredient_key(l.ingredient) IS NOT NULL
ORDER BY public.ingredient_key(l.ingredient), l.ingredient;

-- A name the bottle catalog or the generics backfill already settles is only
-- used when it's here (production has them all); never made fresh, so a
-- re-run of those migrations stays a no-op.
