WITH "added" AS (
    SELECT x.name, 'ingredient', true FROM "mb_ingredients" x WHERE x.id IS NULL
    RETURNING "id", "name"
)
UPDATE "mb_ingredients" x SET "id" = a.id FROM "added" a WHERE x.id IS NULL AND a.name = x.name;

                                "preparation_notes", "is_optional", "sort_order")
SELECT l.item_id, i.id, i.generic_id, l.amount, l.unit, l.prep, false, l.pos
FROM "mb_lines" l
JOIN "mb_ingredients" x ON x.key = public.ingredient_key(l.ingredient)
JOIN "public"."items" i ON i.id = x.id;

