JOIN "mb_ids" p ON p.handle = v.handle
ON CONFLICT ON CONSTRAINT "profile_menu_editions_once" DO NOTHING;

SELECT m.id, d.item_id, x.pos
FROM "mb_menu" x
JOIN "mb_ids" p ON p.handle = x.handle
JOIN "public"."profile_menu_editions" m ON m.profile_id = p.id AND m.name = x.edition AND m.year = x.year
     AND m.month IS NOT DISTINCT FROM x.month::smallint
JOIN "mb_drinks" d ON d.handle = x.handle AND d.name = x.drink
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profile_menu_edition_drinks" o WHERE o.edition_id = m.id AND o.item_id = d.item_id
);

-- --- Put these drinks' flavour jobs back ---

DELETE FROM "private"."item_flavor_jobs" j
USING "mb_drinks" d
WHERE j.item_id = d.item_id AND NOT EXISTS (SELECT 1 FROM "mb_flavor_jobs" o WHERE o.item_id = j.item_id);
UPDATE "private"."item_flavor_jobs" j SET
    "status" = o.status, "revision" = o.revision, "attempts" = o.attempts, "run_after" = o.run_after,
    "lease_until" = o.lease_until, "last_error" = o.last_error, "updated_at" = o.updated_at
FROM "mb_flavor_jobs" o
WHERE j.item_id = o.item_id AND j.revision <> o.revision;

DROP TABLE "mb_flavor_jobs", "mb_ingredients", "mb_menu", "mb_cocreators", "mb_lines", "mb_drinks", "mb_ids", "mb_fill", "mb_bars";

RESET "app.image_worker";
